"use client";

/**
 * Word mark: a sentence settles, then one phrase in it gets marked by hand.
 * A highlighter sweeps behind it, an underline draws, a loose ring goes round
 * it, or a tight box closes on it.
 *
 * Written by Better Design. Painted from the theme prop, so the sentence takes
 * the product's ink and the mark takes its primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { useEffect, useRef, useState } from "react";
import { AbsoluteFill, continueRender, delayRender, useCurrentFrame } from "remotion";
import { easings, pickFont, progress, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER, waitUntilDone } = loadFont("normal", { weights: ["500", "700"], subsets: ["latin"] });

/** How the phrase is marked. */
export type WordMarkVariant = "marker" | "underline" | "circle" | "box";

export interface WordMarkProps {
  /** The whole sentence. It must contain `phrase`. */
  text?: string;
  /** The part of `text` that gets marked. */
  phrase?: string;
  /** `marker` sweeps a highlighter, `underline` draws a line, `circle` rings it, `box` boxes it. */
  variant?: WordMarkVariant;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const MARK_AT = 24;
const MARK_FRAMES = 26;
const SIZE = 104;

/** A wobbly closed loop that runs a little past its start, like a pen ring. */
function ringPath(w: number, h: number): string {
  const cx = w / 2;
  const cy = h / 2;
  const rx = w / 2 + SIZE * 0.32;
  const ry = h / 2 + SIZE * 0.02;
  const points: string[] = [];
  const steps = 72;
  for (let s = 0; s <= steps; s++) {
    const a = -2.5 + (s / steps) * Math.PI * 2.16;
    const grow = 1 + 0.05 * (s / steps) + 0.015 * Math.sin(a * 3);
    points.push(`${(cx + Math.cos(a) * rx * grow).toFixed(1)},${(cy + Math.sin(a) * ry * grow - (s / steps) * 6).toFixed(1)}`);
  }
  return `M${points.join(" L")}`;
}

/** A tight hand-drawn box, starting top left and closing a touch past the corner. */
function boxPath(w: number, h: number): string {
  const p = SIZE * 0.12;
  return `M${-p - 4},${-p + 2} L${w + p},${-p - 3} L${w + p + 3},${h + p} L${-p},${h + p + 2} L${-p + 1},${-p - 6}`;
}

/** A gently arched underline with a small flick at the end. */
function underlinePath(w: number, h: number): string {
  const y = h + SIZE * 0.06;
  return `M${-8},${y + 4} Q${w * 0.5},${y - 10} ${w + 6},${y + 2} Q${w + 14},${y + 4} ${w + 2},${y + 10}`;
}

/** A sentence that settles, then one phrase marked by hand. */
export function WordMark({
  text = "Turn every release into a film people finish",
  phrase = "people finish",
  variant = "marker",
  theme: themeOverride,
  font,
}: WordMarkProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);
  const ref = useRef<HTMLSpanElement>(null);
  const [handle] = useState(() => delayRender("Measure the marked phrase"));
  const [box, setBox] = useState({ w: 0, h: 0 });

  useEffect(() => {
    Promise.all([waitUntilDone(), document.fonts.ready]).then(() => {
      if (ref.current) setBox({ w: ref.current.offsetWidth, h: ref.current.offsetHeight });
      continueRender(handle);
    });
  }, [handle, family]);

  const at = text.indexOf(phrase);
  const before = at >= 0 ? text.slice(0, at) : `${text} `;
  const after = at >= 0 ? text.slice(at + phrase.length) : "";

  const enter = easings.out(progress(frame, 0, 20));
  const draw = easings.inOut(progress(frame, MARK_AT, MARK_FRAMES));
  const ink = easings.out(progress(frame, MARK_AT + MARK_FRAMES * 0.4, 14));

  const stroke = Math.round(SIZE * 0.07);
  const path =
    variant === "circle" ? ringPath(box.w, box.h) : variant === "box" ? boxPath(box.w, box.h) : underlinePath(box.w, box.h);

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family, padding: 180 }}>
      <p
        style={{
          margin: 0,
          maxWidth: 1500,
          textAlign: "center",
          fontSize: SIZE,
          fontWeight: 700,
          lineHeight: 1.34,
          letterSpacing: "-0.03em",
          color: theme.foreground,
          opacity: enter,
          transform: `translateY(${(1 - enter) * 28}px)`,
        }}
      >
        {before}
        <span ref={ref} style={{ position: "relative", display: "inline-block", whiteSpace: "nowrap" }}>
          {variant === "marker" ? (
            <span
              style={{
                position: "absolute",
                left: -SIZE * 0.1,
                right: -SIZE * 0.1,
                top: "18%",
                bottom: "4%",
                borderRadius: `${SIZE * 0.08}px ${SIZE * 0.18}px ${SIZE * 0.1}px ${SIZE * 0.2}px`,
                background: withAlpha(theme.primary, 0.26),
                transform: `rotate(-1.2deg) scaleX(${draw})`,
                transformOrigin: "left center",
              }}
            />
          ) : null}
          <span style={{ position: "relative", opacity: variant === "marker" ? 1 : 1 - ink }}>{phrase}</span>
          {variant !== "marker" ? (
            <span style={{ position: "absolute", left: 0, top: 0, color: theme.primary, opacity: ink }}>{phrase}</span>
          ) : null}
          {variant !== "marker" && box.w > 0 ? (
            <svg
              width={box.w}
              height={box.h}
              style={{ position: "absolute", left: 0, top: 0, overflow: "visible", pointerEvents: "none" }}
            >
              <path
                d={path}
                pathLength={1}
                fill="none"
                stroke={theme.primary}
                strokeWidth={stroke}
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeDasharray="1 1"
                strokeDashoffset={1 - draw}
              />
            </svg>
          ) : null}
        </span>
        {after}
      </p>
    </AbsoluteFill>
  );
}
